mapper.select:
SELECT tr.TAGNAME AS tag, tr.VALUE AS value FROM TB_RAWDATA tr JOIN ( SELECT TAGNAME, MAX(TS) AS last_ts FROM TB_RAWDATA WHERE TAGNAME IN
#{tag}
AND TS <= #{ref_ts} AND TS > DATE_SUB(#{ref_ts}, INTERVAL 15 MINUTE) AND VALUE IS NOT NULL GROUP BY TAGNAME ) m ON m.TAGNAME = tr.TAGNAME AND m.last_ts = tr.TS

SELECT DSTRB_ID AS tag, DATE_FORMAT(RGSTR_TIME, '%Y-%m-%d %H:%i:%s') AS rgstr_time, DATE_FORMAT(PRDCT_TIME, '%Y-%m-%d %H:%i:%s') AS prdct_time, MAX(PRDCT_VALUE) AS value FROM TB_CTR_TNK_RST WHERE RGSTR_TIME >= #{fromTs} AND RGSTR_TIME <= #{toTs} AND UPPER(model_name) = 'XGBOOST' AND DSTRB_ID IN
#{tg}
GROUP BY DSTRB_ID, RGSTR_TIME, PRDCT_TIME
